const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '20' },
      { kind: 'text', payload: '40' },
      { kind: 'text', payload: '60' },
      { kind: 'text', payload: '80' },
      { kind: 'text', payload: '100' }
    ];
  },
  render: function (input, metrics) {
    var values = [0, 20, 40, 60, 80, 100];
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;

    var padX = 64;
    var x0 = padX;
    var x1 = W - padX;
    if (x1 <= x0) { x1 = x0 + 1; }
    var axisY = H - 88;
    if (axisY < 40) { axisY = Math.max(24, H * 0.6); }

    var tickLen = 12;
    var labelDy = 30;
    var fontSize = 16;

    var axisCmds = visualSdk.polyline([[x0, axisY], [x1, axisY]]);

    var tickCmds = [];
    var i;
    for (i = 0; i < values.length; i++) {
      var t = i / (values.length - 1);
      var tx = x0 + (x1 - x0) * t;
      var seg = visualSdk.polyline([[tx, axisY - tickLen / 2], [tx, axisY + tickLen / 2]]);
      tickCmds = tickCmds.concat(seg);
    }

    var headCmds = visualSdk.polyline([
      [x1 - 11, axisY - 5],
      [x1, axisY],
      [x1 - 11, axisY + 5]
    ]);

    var children = [
      { type: 'path', pathId: 'axis', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
      { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
      { type: 'path', pathId: 'head', stroke: '#26354a', strokeWidth: 2, fill: 'none' }
    ];

    for (i = 0; i < values.length; i++) {
      var f = i / (values.length - 1);
      var lx = x0 + (x1 - x0) * f;
      var m = metrics && metrics[i] ? metrics[i] : null;
      var halfW = 0;
      if (m && typeof m.width === 'number') { halfW = m.width / 2; }
      if (lx - halfW < 4) { lx = 4 + halfW; }
      if (lx + halfW > W - 4) { lx = W - 4 - halfW; }
      children.push({
        type: 'label',
        text: String(values[i]),
        x: lx,
        y: axisY + labelDy,
        fontSize: fontSize,
        textAnchor: 'middle',
        fill: '#26354a'
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'axis-0-100-six-ticks',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axisCmds },
        { id: 'ticks', commands: tickCmds },
        { id: 'head', commands: headCmds }
      ],
      root: { type: 'group', children: children }
    };
  }
};
